# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::SnapshotEndpoint do
  it "a failed answer whose body echoes the bearer token logs only its status and a fixed reason" do
    token = "snapshot-endpoint-spec-token-#{SecureRandom.hex(8)}"
    answer = TimekeepingRelay::Response.new(
      status: 502,
      body: { "reason" => "Bearer #{token}\nINFO forged line", "echo" => { "Authorization" => "Bearer #{token}" } }
    )
    inner = Object.new
    inner.define_singleton_method(:deliver) { |_batch, idempotency_key:| answer }
    output = StringIO.new
    logger = Logger.new(output)
    logger.level = Logger::DEBUG

    result = described_class.new(endpoint: inner, logger:).deliver({ "schema_version" => 1, "snapshots" => [] },
                                                                   idempotency_key: "00000000-0000-5000-8000-000000000000")

    expect(result.status).to eq(502)
    # "No token is written to a payload or a log line."
    expect(output.string).to include("502")
    expect(output.string).not_to include(token)
    expect(output.string).not_to include("forged line")
  end
end
